/**
 * What a dumbbell exercise's weight number means (docs/decisions/WORKOUT-SETS.md
 * §Dumbbell weight). Most lifters and apps log one dumbbell ("each"); some
 * log the pair ("total"). Both are fine if consistent, so it's a choice: an
 * account default plus per-exercise overrides, synced in user_preferences
 * and keyed by exercise ref key ('catalog:…' / 'custom:…').
 *
 * It labels the number; it never rewrites stored weights or volume, so
 * switching it is always safe.
 */

export type DumbbellLoad = 'each' | 'total';

export const DUMBBELL_LOADS: readonly DumbbellLoad[] = ['each', 'total'];
export const DUMBBELL_LOAD_DEFAULT: DumbbellLoad = 'each';

/** Short UI labels (segmented control). */
export const DUMBBELL_LOAD_SHORT: Record<DumbbellLoad, string> = { each: 'Each', total: 'Total' };
/** Column-header suffix after the unit (e.g. "KG EACH"). */
export const DUMBBELL_LOAD_HEADER: Record<DumbbellLoad, string> = { each: 'each', total: 'total' };
/** How MCP / Ask describe the number. */
export const DUMBBELL_LOAD_MEANING: Record<DumbbellLoad, string> = {
  each: 'per dumbbell (one hand)',
  total: 'both dumbbells combined',
};

export function isDumbbellLoad(v: unknown): v is DumbbellLoad {
  return v === 'each' || v === 'total';
}

export function isDumbbellExercise(equipment: string | null | undefined): boolean {
  return (equipment ?? '').trim().toLowerCase() === 'dumbbell';
}

/** Keep only well-formed entries (synced payloads are untrusted). */
export function sanitizeDumbbellLoads(v: unknown): Record<string, DumbbellLoad> {
  const out: Record<string, DumbbellLoad> = {};
  if (!v || typeof v !== 'object' || Array.isArray(v)) return out;
  for (const [k, mode] of Object.entries(v as Record<string, unknown>)) {
    if (k.length > 0 && k.length <= 200 && isDumbbellLoad(mode)) out[k] = mode;
  }
  return out;
}

/** Null for non-dumbbell exercises: there's nothing to label. */
export function resolveDumbbellLoad(
  equipment: string | null | undefined,
  overrides: Readonly<Record<string, DumbbellLoad>> | undefined,
  refKey: string | null | undefined,
  fallback: unknown,
): DumbbellLoad | null {
  if (!isDumbbellExercise(equipment)) return null;
  const own = refKey && overrides ? overrides[refKey] : undefined;
  return own ?? (isDumbbellLoad(fallback) ? fallback : DUMBBELL_LOAD_DEFAULT);
}
